private void filtraTable_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
AlphaWebReports.raporteUtil.shtoFiltra(filtraTable, null, AlphaWebReports.raporteUtil.DeserializoParametrat(this.Extensions["filtrat"]));
}

private void Rap_Analize_Cmime_Shitje_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
 xrPictureBox1.Image = AlphaWebReports.raporteUtil.MerrLogoNdermarrje(this.Extensions["ndermarrjeLogo"]);
System.Resources.ResourceManager  rm = new System.Resources.ResourceManager("Resources.Strings",System.Reflection.Assembly.Load("App_GlobalResources"));
var parametraRaporti = AlphaWebReports.raporteUtil.DeserializoParametraPerKonstruktorRaporti(this.Extensions["parametraRaporti"]);
  var parameters = AlphaWebReports.raporteUtil.DeserializoParametrat(this.Extensions["filtrat"]);
      var formati = parameters.Find(param => param.Emri == "filterFormatNumri");
	string shifraPasPresjes = (formati != null) ? formati.Vlera : "2";	

  // Percakton kolonat e pivot grides
            DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField fieldKodi = new DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField("Kodi", DevExpress.XtraPivotGrid.PivotArea.RowArea);
            fieldKodi.FieldName = "KODARTIKULLI";
            fieldKodi.Caption = rm.GetString("cmbCmimeArtikulliCaptionKodi", parametraRaporti.Ci);

            DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField fieldPershkrimArtikulli = new DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField("Pershkrimi", DevExpress.XtraPivotGrid.PivotArea.RowArea);
            fieldPershkrimArtikulli.FieldName = "PERSHKRIMARTIKULLI";
            fieldPershkrimArtikulli.Caption = rm.GetString("labelRaportiPershkrimi", parametraRaporti.Ci);

            DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField fieldFurnitori = new DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField("Furnitori", DevExpress.XtraPivotGrid.PivotArea.RowArea);
            fieldFurnitori.FieldName = "FURNITORIKRYESOR";
            fieldFurnitori.Caption = rm.GetString("lblFurnKryesor", parametraRaporti.Ci);

            DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField fieldGrupimi1 = new DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField("Grupimi", DevExpress.XtraPivotGrid.PivotArea.RowArea);
            fieldGrupimi1.FieldName = "GRUPIMI1";
            fieldGrupimi1.Caption = rm.GetString("labelGrupimKlientPare", parametraRaporti.Ci);

            DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField fieldGrupimi2 = new DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField("Grupimi2", DevExpress.XtraPivotGrid.PivotArea.RowArea);
            fieldGrupimi2.FieldName = "GRUPIMI2";
            fieldGrupimi2.Caption = rm.GetString("labelGrupimKlientDyte", parametraRaporti.Ci);


            DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField fieldNjesia = new DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField("Njesia1", DevExpress.XtraPivotGrid.PivotArea.RowArea);
            fieldNjesia.FieldName = "NJESIA1";
            fieldNjesia.Caption = rm.GetString("labelNjesia1", parametraRaporti.Ci);

            DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField fieldNjesia2 = new DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField("Njesia2", DevExpress.XtraPivotGrid.PivotArea.RowArea);
            fieldNjesia2.FieldName = "NJESIA2";
            fieldNjesia2.Caption = rm.GetString("labelNjesia2", parametraRaporti.Ci);

            DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField fieldKoeficenti = new DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField("Koeficenti", DevExpress.XtraPivotGrid.PivotArea.RowArea);
            fieldKoeficenti.FieldName = "KOEFICENTARTIKULLI";
            fieldKoeficenti.Caption = rm.GetString("lblKoef", parametraRaporti.Ci);
            fieldKoeficenti.CellFormat.FormatType = DevExpress.Utils.FormatType.Numeric;
            fieldKoeficenti.ValueFormat.FormatType = DevExpress.Utils.FormatType.Numeric;
            fieldKoeficenti.ValueFormat.FormatString = "F" + shifraPasPresjes;
            DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField fieldBlerje = new DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField("Blerje", DevExpress.XtraPivotGrid.PivotArea.RowArea);
            fieldBlerje.FieldName = "HYRJE";
            fieldBlerje.Caption = rm.GetString("lblSasiaBlerje", parametraRaporti.Ci);
            fieldBlerje.CellFormat.FormatType = DevExpress.Utils.FormatType.Numeric;
            fieldBlerje.CellFormat.FormatString = "F" + shifraPasPresjes;
            fieldBlerje.CellFormat.FormatType = DevExpress.Utils.FormatType.Numeric;
            fieldBlerje.ValueFormat.FormatType = DevExpress.Utils.FormatType.Numeric;
            fieldBlerje.ValueFormat.FormatString = "F" + shifraPasPresjes; 
            DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField fieldShitje = new DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField("Shitje", DevExpress.XtraPivotGrid.PivotArea.RowArea);
            fieldShitje.FieldName = "DALJE";
            fieldShitje.Caption = rm.GetString("lblSasiashitje", parametraRaporti.Ci);
            fieldShitje.CellFormat.FormatType = DevExpress.Utils.FormatType.Numeric;
            fieldShitje.CellFormat.FormatString = "F" + shifraPasPresjes;
            fieldShitje.CellFormat.FormatType = DevExpress.Utils.FormatType.Numeric;
            fieldShitje.ValueFormat.FormatType = DevExpress.Utils.FormatType.Numeric;
            fieldShitje.ValueFormat.FormatString = "F" + shifraPasPresjes; 
            DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField fieldGjendje = new DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField("Gjendje", DevExpress.XtraPivotGrid.PivotArea.RowArea);
            fieldGjendje.FieldName = "GJENDJASASI";
            fieldGjendje.Caption = rm.GetString("labelRaportGjendje", parametraRaporti.Ci);
            fieldGjendje.CellFormat.FormatType = DevExpress.Utils.FormatType.Numeric;
            fieldGjendje.ValueFormat.FormatType = DevExpress.Utils.FormatType.Numeric;
            fieldGjendje.ValueFormat.FormatString = "F" + shifraPasPresjes; 
            DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField fieldKosto = new DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField("Kosto", DevExpress.XtraPivotGrid.PivotArea.RowArea);
            fieldKosto.FieldName = "KOSTO";
            fieldKosto.Caption = rm.GetString("labelRaportKosto", parametraRaporti.Ci);
            fieldKosto.CellFormat.FormatType = DevExpress.Utils.FormatType.Numeric;
            fieldKosto.ValueFormat.FormatType = DevExpress.Utils.FormatType.Numeric;
            fieldKosto.ValueFormat.FormatString = "F" + shifraPasPresjes; 
            DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField fieldVlefta = new DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField("Vlera", DevExpress.XtraPivotGrid.PivotArea.RowArea);
            fieldVlefta.FieldName = "GJENDJEVLEFTA";
            fieldVlefta.Caption = rm.GetString("labelRaportVlefta", parametraRaporti.Ci);
            fieldVlefta.CellFormat.FormatType = DevExpress.Utils.FormatType.Numeric;
            fieldVlefta.ValueFormat.FormatType = DevExpress.Utils.FormatType.Numeric;
            fieldVlefta.ValueFormat.FormatString = "F" + shifraPasPresjes; 

            DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField fieldNivelCmimi = new DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField("Cmimet", DevExpress.XtraPivotGrid.PivotArea.ColumnArea);
            fieldNivelCmimi.FieldName = "KODNIVELCMIMI";
            fieldNivelCmimi.Caption = rm.GetString("labelRaportiCmimet", parametraRaporti.Ci);

            DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField fieldVleraCmimi = new DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField("Cmimet", DevExpress.XtraPivotGrid.PivotArea.DataArea);
            fieldVleraCmimi.FieldName = "CMIMI";
            fieldVleraCmimi.Caption = rm.GetString("labelRaportiCmimet", parametraRaporti.Ci);
            fieldVleraCmimi.CellFormat.FormatType = DevExpress.Utils.FormatType.Numeric;
            fieldVleraCmimi.CellFormat.FormatString = "F" + shifraPasPresjes;

             cmimetPivotGrid.Fields.Clear();
            cmimetPivotGrid.Fields.AddRange(new DevExpress.XtraReports.UI.PivotGrid.XRPivotGridField[] {fieldKodi,  fieldPershkrimArtikulli,
                fieldFurnitori, fieldGrupimi1, fieldGrupimi2, fieldNjesia, fieldNjesia2, fieldKoeficenti, fieldBlerje, fieldShitje, fieldGjendje, fieldKosto,
                fieldVlefta ,fieldNivelCmimi, fieldVleraCmimi});


            cmimetPivotGrid.Styles.FieldHeaderStyle = cmimetPivotGrid.Styles.FieldHeaderStyle;
            cmimetPivotGrid.Styles.FieldValueStyle = cmimetPivotGrid.Styles.FieldHeaderStyle;
            cmimetPivotGrid.FieldValueGrandTotalStyleName = cmimetPivotGrid.Styles.FieldHeaderStyle.Name;

}

private void PageHeader_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
 this.DataSource = null;
}
